    /// <summary>Holds the pooled source of <c>OnityTask.WhenAll</c> over two typed tasks.</summary>
    internal static class OnityWhenAllTuple<T1, T2>
    {
        /// <summary>Native single-consumer source of one pending output; reused after release.</summary>
        internal sealed class Source :
            OnityWhenAllTupleTaskSourceBase<(T1, T2)>,
            IOnityPooledRunner<Source>
        {
            private const int k_inputCount = 2;

            private static OnityRunnerPool<Source> s_pool;

            private Source m_nextPooled;
            private OnityTask<T1> m_task1;
            private OnityTask<T2> m_task2;
            private T1 m_result1;
            private T2 m_result2;

            private Source() : base(k_inputCount)
            {
            }

            ref Source IOnityPooledRunner<Source>.NextPooled => ref m_nextPooled;

            internal static Source Rent(
                OnityTask<T1> task1,
                OnityTask<T2> task2,
                bool validateInputs)
            {
                // A contended rent allocates instead of waiting.
                if (!s_pool.TryPop(out Source source))
                {
                    source = new Source();
                }

                source.m_task1 = task1;
                source.m_task2 = task2;
                if (validateInputs)
                {
                    int duplicate = OnityTaskComposition.FindDuplicateInput(source, k_inputCount);
                    if (duplicate >= 0)
                    {
                        source.ClearInputs();
                        source.ReturnToPool();
                        OnityTaskComposition.ThrowDuplicateInput(OnityTaskComposition.k_whenAll, duplicate);
                    }
                }

                source.Initialize();
                return source;
            }

            public override bool TryGetInputIdentity(int index, out OnityWhenAnyInputIdentity identity)
            {
                switch (index)
                {
                    case 0:
                        return m_task1.TryGetWhenAnyIdentity(out identity);
                    default:
                        return m_task2.TryGetWhenAnyIdentity(out identity);
                }
            }

            protected override void RegisterInput(int index, Action callback)
            {
                switch (index)
                {
                    case 0:
                        m_task1.RegisterWhenAnyObserver(callback);
                        return;
                    default:
                        m_task2.RegisterWhenAnyObserver(callback);
                        return;
                }
            }

            protected override OnityTaskSourceStatus ReadInput(
                int index,
                out Exception fault,
                out CancellationToken cancellationToken)
            {
                switch (index)
                {
                    case 0:
                        return m_task1.ReadWhenAnyOutcome(out m_result1, out fault, out cancellationToken);
                    default:
                        return m_task2.ReadWhenAnyOutcome(out m_result2, out fault, out cancellationToken);
                }
            }

            protected override (T1, T2) CreateResult()
            {
                return (
                    m_result1,
                    m_result2);
            }

            protected override void ClearInput(int index)
            {
                switch (index)
                {
                    case 0:
                        m_task1 = default;
                        return;
                    default:
                        m_task2 = default;
                        return;
                }
            }

            protected override void ClearInputs()
            {
                m_task1 = default;
                m_task2 = default;
                m_result1 = default;
                m_result2 = default;
            }

            protected override void ReturnToPool()
            {
                // A contended or full return lets the source be collected.
                s_pool.TryPush(this, OnityTaskSettings.s_sourcePoolCapacity);
            }
        }
    }

